Create two files. Concise. No decorative comments.

FILE 1: packages/engine/src/skillMetrics.ts
Export only:
  interface SessionAnalytics{id:string;player_id:string;mode:string;seed_hash:string;started_at:string;ended_at:string|null;total_chains:number;scoring_chains:number;farkle_count:number;banks_taken:number;peak_multiplier:number;final_banked:number;final_score:number;avg_chain_score:number;skill_score:number}
  interface ChainDecision{id:string;session_id:string;player_id:string;chain_number:number;faces_played:number[];score_result:number;multiplier_at:number;unbanked_before:number;decision:'CONTINUE'|'BANK'|'PASS'|'FARKLE';was_optimal:boolean;timestamp:string}
  function computeSkillScore(s:Omit<SessionAnalytics,'skill_score'>):number
    chainQuality=s.scoring_chains/s.total_chains
    bankEfficiency=s.peak_multiplier/4.0
    farkleResistance=1-(s.farkle_count/s.total_chains)
    return (chainQuality*0.4)+(bankEfficiency*0.35)+(farkleResistance*0.25) clamped 0-1
  function isOptimalDecision(decision:'BANK'|'CONTINUE',unbanked:number,step:number,risk:number):boolean
    STEPS=[1.0,1.25,1.5,2.0,3.0,4.0]
    ev=unbanked*(1-risk)*STEPS[Math.min(step+1,5)]
    CONTINUE optimal when ev>unbanked
  function estimateFarkleRisk(f1:number,f5:number,total:number):number
    if total===0 return 0.9
    scoringRatio=(f1+f5)/total
    return Math.max(0,Math.min(1,0.9-(scoringRatio*1.5)))
No imports from apps/. No Math.random().

FILE 2: apps/server/src/analytics.ts
import {SessionAnalytics,ChainDecision,computeSkillScore} from '@farkle/engine/skillMetrics'
import {createClient} from '@supabase/supabase-js'
const sb=createClient(process.env.SUPABASE_URL!,process.env.SUPABASE_SERVICE_KEY!)
export async function insertSession(s:Omit<SessionAnalytics,'skill_score'>):Promise<void>{try{const skill_score=computeSkillScore(s);await sb.from('session_analytics').upsert({...s,skill_score})}catch{}}
export async function insertChainDecision(d:ChainDecision):Promise<void>{try{await sb.from('chain_decisions').insert(d)}catch{}}
export async function getSkillPercentile(player_id:string):Promise<number>{try{const{data}=await sb.from('session_analytics').select('skill_score').eq('player_id',player_id).order('started_at',{ascending:false}).limit(100);if(!data?.length)return 0;return data.reduce((a,r)=>a+r.skill_score,0)/data.length}catch{return 0}}
export async function getSkillDifferentialReport():Promise<{topDecile:number;bottomHalf:number;ratio:number}>{try{const{data}=await sb.from('session_analytics').select('skill_score,final_score').order('skill_score',{ascending:false});if(!data?.length)return{topDecile:0,bottomHalf:0,ratio:1};const top=data.slice(0,Math.ceil(data.length*0.1));const bot=data.slice(Math.floor(data.length*0.5));const topDecile=top.reduce((a,r)=>a+r.final_score,0)/top.length;const bottomHalf=bot.reduce((a,r)=>a+r.final_score,0)/bot.length;return{topDecile,bottomHalf,ratio:topDecile/Math.max(1,bottomHalf)}}catch{return{topDecile:0,bottomHalf:0,ratio:1}}}

